package org.eclipse.rdf4j.workbench.proxy.config;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.net.URL;
import java.net.URLClassLoader;
import java.nio.file.Files;
import java.nio.file.Path;

import org.eclipse.rdf4j.common.app.AppConfiguration;
import org.eclipse.rdf4j.common.app.config.Configuration;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.api.parallel.ResourceLock;
import org.springframework.mock.web.MockServletContext;

import jakarta.servlet.ServletContext;

@ResourceLock("thread-context-class-loader")
class WorkbenchPolicyLoaderTest {

	@TempDir
	Path tempDir;

	@Test
	void packagedDefaultsClasspathOverridesAndExternalOverridesUsePrecedenceOrder() throws Exception {
		Path dataDirectory = tempDir.resolve("data");
		Path externalFile = dataDirectory.resolve(Configuration.DIR).resolve("workbench.properties");
		Files.createDirectories(externalFile.getParent());
		Files.writeString(externalFile,
				"menu.group.explore.order=27\n"
						+ "menu.item.query.label=External query\n");

		Path classpathRoot = tempDir.resolve("classpath");
		Path classpathFile = classpathRoot.resolve("org/eclipse/rdf4j/common/app/config/workbench.properties");
		Files.createDirectories(classpathFile.getParent());
		Files.writeString(classpathFile,
				"menu.group.explore.order=17\n"
						+ "menu.item.query.label=Classpath query\n"
						+ "theme.deployment-default=dark\n");

		Thread thread = Thread.currentThread();
		ClassLoader originalClassLoader = thread.getContextClassLoader();
		try (URLClassLoader testClassLoader = new URLClassLoader(
				new URL[] { classpathRoot.toUri().toURL() }, originalClassLoader) {
			@Override
			public URL getResource(String name) {
				return super.getResource(name.startsWith("/") ? name.substring(1) : name);
			}
		}) {
			thread.setContextClassLoader(testClassLoader);

			AppConfiguration appConfiguration = mock(AppConfiguration.class);
			when(appConfiguration.getDataDir()).thenReturn(dataDirectory.toFile());
			ServletContext servletContext = new MockServletContext();
			WorkbenchPolicy policy = WorkbenchPolicyLoader.getPolicy(servletContext, appConfiguration);

			assertThat(policy.getVisibleMenuItems()
					.stream()
					.filter(item -> "query".equals(item.getId()))
					.map(WorkbenchPolicy.MenuItem::getLabel)
					.toList()).containsExactly("External query");
			assertThat(policy.getVisibleMenuGroups()
					.stream()
					.filter(group -> "explore".equals(group.getId()))
					.map(WorkbenchPolicy.MenuGroup::getOrder)
					.toList()).containsExactly(27);
			assertThat(policy.getDeploymentThemeDefault()).isEqualTo("dark");
			assertThat(policy.getVisibleMenuGroups()
					.stream()
					.filter(group -> "server".equals(group.getId()))
					.map(WorkbenchPolicy.MenuGroup::getLabel)
					.toList()).containsExactly("Server");
		} finally {
			thread.setContextClassLoader(originalClassLoader);
		}
	}
}
